import { chromium } from '/home/vercel-sandbox/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/index.mjs';

const browser = await chromium.launch({
  args: ['--no-sandbox'],
  executablePath: '/home/vercel-sandbox/.cache/ms-playwright/chromium-1234/chrome-linux64/chrome',
});

async function run(reducedMotion, label) {
  const context = await browser.newContext({ reducedMotion: reducedMotion ? 'reduce' : 'no-preference' });
  const page = await context.newPage();

  await page.goto('http://localhost:3311/', { waitUntil: 'networkidle' });
  // warm up navigation (prefetch/compile) by hovering, then wait a bit
  await page.hover('a.product-card >> nth=0');
  await page.waitForTimeout(300);

  // Start polling animations right after click
  const link = page.locator('a.product-card').first();
  await link.click();

  const samples = [];
  const start = Date.now();
  while (Date.now() - start < 900) {
    const info = await page.evaluate(() => {
      const anims = document.getAnimations();
      return {
        t: performance.now(),
        count: anims.length,
        names: anims.map((a) => a.animationName || a.constructor.name).slice(0, 10),
        h1: document.querySelector('h1')?.textContent,
      };
    }).catch(() => null);
    if (info) samples.push({ ...info, elapsed: Date.now() - start });
    await page.waitForTimeout(40);
  }
  console.log(label, JSON.stringify(samples.filter((s) => s.count > 0 || true).map(s => ({e: s.elapsed, c: s.count, n: s.names, h1: s.h1}))));

  await context.close();
}

await run(false, 'motion');
await run(true, 'reduced');

await browser.close();
